import rows from './usLandCells.json';
import type { SweepCell } from './meetingSweep';

/**
 * Base cells for the Meeting Guide sweep: all US land, including Alaska, Hawaii and
 * the territories, and no open water, Canada or Mexico. Generated by
 * scripts/generateUsLandCells.mjs. Rows are "south|latStep|lngStep|west:count,...".
 */
export function usBaseCells(): SweepCell[] {
  const cells: SweepCell[] = [];
  for (const row of rows as string[]) {
    const [south, latStep, lngStep, runs] = row.split('|');
    const s = Number(south);
    const n = s + Number(latStep);
    const width = Number(lngStep);
    for (const run of runs.split(',')) {
      const [west, count] = run.split(':').map(Number);
      for (let i = 0; i < count; i++) {
        cells.push({ s, n, w: west + i * width, e: west + (i + 1) * width });
      }
    }
  }
  return cells;
}
